# Uji 0006: izin library dan playbook (mempersempit dari board), Penulis, saklar sembunyikan, penugasan mengikuti rantai izin.
M4="f0000000-0000-0000-0000-0000000000f4"; L1="f0000000-0000-0000-0000-0000000000a1"; L2="f0000000-0000-0000-0000-0000000000a2"
P1="f0000000-0000-0000-0000-0000000000b1"; P2="f0000000-0000-0000-0000-0000000000b2"; P3="f0000000-0000-0000-0000-0000000000b3"
sh(db,"update profiles set active=true")
sh(db,f"insert into boards (id,name,created_by) values ('{M4}','Board M4','{UID('dhaka')}')")
sh(db,f"insert into board_holdings values ('{M4}','people'),('{M4}','sib')")
sh(db,f"insert into libraries (id,board_id,name) values ('{L1}','{M4}','L1'),('{L2}','{M4}','L2')")
sh(db,f"insert into playbooks (id,library_id,name) values ('{P1}','{L1}','P1'),('{P2}','{L1}','P2'),('{P3}','{L2}','P3')")
for i,(p,t) in enumerate([(P1,'C1'),(P2,'C2'),(P3,'C3')]):
    sh(db,f"insert into cards (playbook_id,title,created_by) values ('{p}','{t}','{UID('dhaka')}')")
    q('dhaka',f"select publish_card((select id from cards where title='{t}'),'kecil',null)")
sh(db,"insert into groups (holding_id,name) values ('sib','Tim M4')")
sh(db,f"insert into group_members select id,'{UID('rudi')}' from groups where name='Tim M4'")
print('--- 0006 dasar')
expect('Dimas lihat 3 playbook sebelum ada pembatasan','dimas',cnt('playbooks',f"id in ('{P1}','{P2}','{P3}')"),3)
expect('Kolom baru: bawaan interval 3 bulan dan tidak disembunyikan','dhaka',f"select review_interval||hidden from playbooks where id='{P1}'",'3mfalse')
print('--- 0006 library dipersempit ke grup')
expect('Ayu persempit L1 ke grup Tim M4','ayu',f"insert into library_access (library_id,holding_id,subject_type,group_id,role) select '{L1}','sib','group',id,'pembaca' from groups where name='Tim M4'; select count(*) from library_access",1)
expect('Rudi (anggota grup) tetap lihat L1','rudi',cnt('libraries',f"id='{L1}'"),1)
expect('Dimas tidak lihat L1','dimas',cnt('libraries',f"id='{L1}'"),0)
expect('Dimas tetap lihat L2 (tanpa pembatasan)','dimas',cnt('libraries',f"id='{L2}'"),1)
expect('Dimas tidak lihat playbook di L1','dimas',cnt('playbooks',f"id in ('{P1}','{P2}')"),0)
expect('Dimas tidak lihat card di L1','dimas',cnt('cards',"title in ('C1','C2')"),0)
expect('Dimas masih lihat board','dimas',cnt('boards',f"id='{M4}'"),1)
expect('Ayu admin tetap lihat L1','ayu',cnt('libraries',f"id='{L1}'"),1)
print('--- 0006 playbook dipersempit ke unit')
expect('Ayu persempit P3 ke unit Operasional','ayu',f"insert into playbook_access (playbook_id,holding_id,subject_type,unit,role) values ('{P3}','sib','unit','Operasional','pembaca'); select count(*) from playbook_access",1)
expect('Dimas (Operasional) lihat P3','dimas',cnt('playbooks',f"id='{P3}'"),1)
expect('Rudi (Finance) tidak lihat P3','rudi',cnt('playbooks',f"id='{P3}'"),0)
print('--- 0006 Tanpa akses untuk semua pengguna holding')
expect('Ayu set L2 Tanpa akses untuk SIB','ayu',f"insert into library_access (library_id,holding_id,subject_type,role) values ('{L2}','sib','all','pembaca'); select count(*) from library_access where subject_type='all'",1)
expect('Dimas tidak lagi lihat L2','dimas',cnt('libraries',f"id='{L2}'"),0)
expect('Dimas tidak lagi lihat P3 walau unitnya cocok','dimas',cnt('playbooks',f"id='{P3}'"),0)
expect('Ayu tetap lihat L2','ayu',cnt('libraries',f"id='{L2}'"),1)
print('--- 0006 validasi izin')
expect('Dimas tidak bisa menulis izin','dimas',f"insert into library_access (library_id,holding_id,subject_type,unit,role) values ('{L1}','sib','unit','X','pembaca')",err=True)
expect('Pembaca di holding PEOPLE ditolak','dhaka',f"insert into library_access (library_id,holding_id,subject_type,unit,role) values ('{L1}','people','unit','X','pembaca')",err=True)
expect('Holding yang tidak membuka board ditolak (BEJO)','dhaka',f"insert into library_access (library_id,holding_id,subject_type,unit,role) values ('{L1}','bejo','unit','X','pembaca')",err=True)
expect('Orang di luar holding ditolak (Intan hanya PEOPLE)','ayu',f"insert into playbook_access (playbook_id,holding_id,subject_type,profile_id,role) values ('{P1}','sib','user','{UID('intan')}','pembaca')",err=True)
expect('Grup holding lain ditolak','dhaka',f"insert into playbook_access (playbook_id,holding_id,subject_type,group_id,role) select '{P1}','sib','group',id from groups where holding_id='bejo' limit 1",err=True)
print('--- 0006 Penulis')
expect('Editor harus admin: Dimas ditolak','dhaka',f"insert into playbook_access (playbook_id,holding_id,subject_type,profile_id,role) values ('{P1}','people','user','{UID('dimas')}','editor')",err=True)
expect('Sebelum ada Penulis, Ayu bisa ubah P1','ayu',"update playbooks set description='x' where id='"+P1+"'; select count(*) from playbooks where description='x'",1)
expect('Dhaka jadikan Intan Penulis P1','dhaka',f"insert into playbook_access (playbook_id,holding_id,subject_type,profile_id,role) values ('{P1}','people','user','{UID('intan')}','editor'); select count(*) from playbook_access where role='editor'",1)
expect('Setelah ada Penulis, Ayu tidak bisa ubah P1','ayu',"update playbooks set description='y' where id='"+P1+"'; select count(*) from playbooks where description='y'",0)
expect('Ayu tidak bisa ubah card di P1','ayu',"update cards set title='C1x' where title='C1'; select count(*) from cards where title='C1x'",0)
expect('Ayu tidak bisa menerbitkan card di P1','ayu',"select publish_card((select id from cards where title='C1'),'kecil',null)",err=True)
expect('Intan (Penulis) bisa ubah P1','intan',"update playbooks set description='z' where id='"+P1+"'; select count(*) from playbooks where description='z'",1)
expect('Ayu tetap bisa ubah P2 (bukan P1)','ayu',"update playbooks set description='w' where id='"+P2+"'; select count(*) from playbooks where description='w'",1)
expect('Ayu tidak bisa ubah L2 kalau ada Penulis L1? (L2 terpisah, tetap bisa)','ayu',"update libraries set description='q' where id='"+L2+"'; select count(*) from libraries where description='q'",1)
print('--- 0006 sembunyikan playbook')
sh(db,f"delete from library_access where library_id='{L1}'")
expect('Dimas lihat P2 lagi setelah pembatasan L1 dicabut','dimas',cnt('playbooks',f"id='{P2}'"),1)
expect('Ayu sembunyikan P2','ayu',f"update playbooks set hidden=true where id='{P2}'; select count(*) from playbooks where hidden",1)
expect('Dimas tidak lihat P2 yang disembunyikan','dimas',cnt('playbooks',f"id='{P2}'"),0)
expect('Dimas tidak lihat card P2','dimas',cnt('cards',"title='C2'"),0)
expect('Ayu tetap lihat P2 tersembunyi','ayu',cnt('playbooks',f"id='{P2}'"),1)
expect('Dimas tidak bisa baca-tandai card P2','dimas',"select mark_read((select id from cards where title='C2'))",err=True)
print('--- 0006 penugasan mengikuti rantai izin')
sh(db,f"delete from playbook_access where playbook_id='{P1}'")
expect('Ayu tugaskan P1 ke Dimas','ayu',f"insert into playbook_requirements (playbook_id,holding_id,due_on,target_type,profile_id) values ('{P1}','sib','2099-01-01','user','{UID('dimas')}'); select count(*) from playbook_requirements where playbook_id='{P1}' and target_type='user'",1)
expect('Dimas tandai sudah baca card P1','dimas',"select mark_read((select id from cards where title='C1')); select count(*) from read_receipts where profile_id='"+UID('dimas')+"' and card_id=(select id from cards where title='C1')",1)
sh(db,f"insert into playbook_access (playbook_id,holding_id,subject_type,group_id,role) select '{P1}','sib','group',id,'pembaca' from groups where name='Tim M4'")
expect('Dimas tidak lagi lihat P1 setelah dipersempit ke grup','dimas',cnt('playbooks',f"id='{P1}'"),0)
expect('Penugasan ke orang yang tidak bisa membaca ditolak (Dua Holding)','ayu',f"insert into playbook_requirements (playbook_id,holding_id,due_on,target_type,profile_id) values ('{P1}','sib','2099-01-01','user','{UID('dua')}')",err=True)
expect('Penugasan ke anggota grup yang bisa membaca diterima (Rudi)','ayu',f"insert into playbook_requirements (playbook_id,holding_id,due_on,target_type,profile_id) values ('{P1}','sib','2099-01-01','user','{UID('rudi')}'); select count(*) from playbook_requirements where profile_id='{UID('rudi')}'",1)
print('--- 0006 audit')
expect('Audit mencatat izin playbook','dhaka',"select count(*)>0 from audit_log where action like 'playbook.access.%'",'t')
